schemas.schema-01-actors.prisma:
/// Authenticated user accounts who can login and manage their personal todo
/// items. Includes credentials and audit information. Uniquely identified by
/// UUID. Soft deletable for account deactivation.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User's unique email address for authentication and contact.
  email String

  /// Hashed password for secure authentication.
  password_hash String

  /// Timestamp when the user account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the user account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp to mark user deactivation.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  todo_user_sessions todo_user_sessions[]
  todo_todo_items todo_todo_items[]

  @@unique([email])
}

/// Sessions for authenticated users maintaining JWTs for access control and
/// expiration. Each session references an existing user and records
/// connection context like IP and referrer.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Referenced user's {@link todo_users.id}.
  todo_user_id String @db.Uuid

  /// IP address of the session client.
  ip String

  /// URL from which the session was established.
  href String

  /// Referrer URL of the session request.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires or ends.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  todoUser todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id, created_at])
}

schemas.schema-02-todos.prisma:
/// Todo items entity storing user tasks with ownership and task details
/// including description, status, due date, and timestamps for creation,
/// update, and soft deletion. Each todo is owned by a unique user identified
/// by todo_users.id. This table supports independent CRUD operations for
/// todo items managed by authenticated users.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_todo_items {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner user identifier referencing todo_users.id
  todo_user_id String @db.Uuid

  /// Text description of the todo item, mandatory, max 255 characters.
  description String

  /// Status of the todo item, either 'pending' or 'completed'.
  status String

  /// Optional due date for task completion; if provided must not be in the
  /// past.
  due_date DateTime? @db.Timestamptz

  /// Timestamp when the todo item was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the todo item was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the todo item was soft deleted; null means active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user todo_users @relation(fields: [todo_user_id], references: [id], onDelete: Cascade)

  @@index([todo_user_id, created_at])
}

