import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test the user registration process by creating a new user account.
 *
 * This test validates that the system accepts a valid user registration request
 * consisting of a unique email and password in plain text, securely stores the
 * password, issues JWT access and refresh tokens, and returns authorized user
 * information without requiring prior authentication.
 *
 * The test performs the following steps:
 *
 * 1. Generate a unique email address and a secure password.
 * 2. Call the user join API endpoint with the user data.
 * 3. Verify the output matches the ITodoUser.IAuthorized DTO.
 * 4. Assert the returned ID is a valid UUID.
 * 5. Assert the returned access token string is non-empty.
 * 6. Assert the token expiration dates are valid ISO date-time strings.
 *
 * This test ensures the critical user registration flow works as expected,
 * providing a foundation for user authentication in subsequent workflows.
 */
export async function test_api_user_registration(connection: api.IConnection) {
  // Step 1: Generate unique email and password
  const email: string = `${RandomGenerator.name(2).replace(/\s+/g, ".")}@example.com`;
  const password: string = RandomGenerator.alphaNumeric(12);

  // Step 2: Create user join request body
  const createBody = {
    email: email,
    password: password,
  } satisfies ITodoUser.ICreate;

  // Step 3: Call the join API
  const authorizedUser: ITodoUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: createBody,
    });

  // Step 4: Validate the output structure
  typia.assert(authorizedUser);

  // Step 5: Assertions on returned data
  TestValidator.predicate(
    "verified valid UUID format for user ID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      authorizedUser.id,
    ),
  );

  TestValidator.predicate(
    "non-empty access token string",
    typeof authorizedUser.token.access === "string" &&
      authorizedUser.token.access.length > 0,
  );

  TestValidator.predicate(
    "non-empty refresh token string",
    typeof authorizedUser.token.refresh === "string" &&
      authorizedUser.token.refresh.length > 0,
  );

  TestValidator.predicate(
    "valid ISO date-time string for expired_at",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?Z$/.test(
      authorizedUser.token.expired_at,
    ),
  );

  TestValidator.predicate(
    "valid ISO date-time string for refreshable_until",
    /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?Z$/.test(
      authorizedUser.token.refreshable_until,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Test the user login process for an existing user.
 *
 * This function creates a new user account, then performs login with the
 * created user credentials. It validates the successful login flow, including
 * assertion of issued JWT tokens and returned user information.
 *
 * Steps:
 *
 * 1. Create user with random but valid email and password using the join endpoint.
 * 2. Log in using the same email and password.
 * 3. Assert that the login response includes valid JWT tokens and matching user
 *    ID.
 */
export async function test_api_user_login_existing_user(
  connection: api.IConnection,
) {
  // 1. Create a new user account
  const email: string = typia.random<string & tags.Format<"email">>();
  const password = RandomGenerator.alphaNumeric(12);

  const createdUser: ITodoUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: {
        email: email,
        password: password,
      } satisfies ITodoUser.ICreate,
    });
  typia.assert(createdUser);

  // 2. Log in with the created user
  const loginUser: ITodoUser.IAuthorized = await api.functional.auth.user.login(
    connection,
    {
      body: {
        email: email,
        password: password,
        ip: null,
        href: "http://localhost/login",
        referrer: "http://localhost/",
      } satisfies ITodoUser.ILogin,
    },
  );
  typia.assert(loginUser);

  // 3. Validate the login response
  TestValidator.predicate("login returned user id", loginUser.id.length > 0);
  TestValidator.equals(
    "login user id matches created user id",
    loginUser.id,
    createdUser.id,
  );

  TestValidator.predicate(
    "login returned token access",
    typeof loginUser.token.access === "string" &&
      loginUser.token.access.length > 0,
  );
  TestValidator.predicate(
    "login returned token refresh",
    typeof loginUser.token.refresh === "string" &&
      loginUser.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "login token expired_at is valid ISO date",
    !isNaN(Date.parse(loginUser.token.expired_at)),
  );
  TestValidator.predicate(
    "login token refreshable_until is valid ISO date",
    !isNaN(Date.parse(loginUser.token.refreshable_until)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

export async function test_api_user_retrieve_by_email(
  connection: api.IConnection,
) {
  // 1. Authenticate and create a new user account
  const userCreateBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(10),
  } satisfies ITodoUser.ICreate;

  const authorizedUser: ITodoUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: userCreateBody,
    });
  typia.assert(authorizedUser);

  // 2. Create a todo user matching the email
  const todoUserCreateBody = {
    email: userCreateBody.email,
    password: userCreateBody.password,
  } satisfies ITodoUser.ICreate;

  const todoUser: ITodoUser = await api.functional.todo.todoUsers.create(
    connection,
    {
      body: todoUserCreateBody,
    },
  );
  typia.assert(todoUser);

  TestValidator.equals(
    "created todo user email equals input email",
    todoUser.email,
    userCreateBody.email,
  );

  // 3. Retrieve the user details by email
  const retrievedUser: ITodoUser = await api.functional.todo.user.todoUsers.at(
    connection,
    {
      todoUserEmail: todoUser.email,
    },
  );
  typia.assert(retrievedUser);

  TestValidator.equals(
    "retrieved user id equals created user id",
    retrievedUser.id,
    todoUser.id,
  );
  TestValidator.equals(
    "retrieved user email equals created email",
    retrievedUser.email,
    todoUser.email,
  );
  TestValidator.equals(
    "retrieved user created_at equals created created_at",
    retrievedUser.created_at,
    todoUser.created_at,
  );
  TestValidator.equals(
    "retrieved user updated_at equals created updated_at",
    retrievedUser.updated_at,
    todoUser.updated_at,
  );
  TestValidator.equals(
    "retrieved user deleted_at equals created deleted_at",
    retrievedUser.deleted_at ?? null,
    todoUser.deleted_at ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

export async function test_api_user_update_by_email(
  connection: api.IConnection,
) {
  // 1. Authenticate new user by calling join API
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string = RandomGenerator.alphaNumeric(12);
  const authorizedUser: ITodoUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: {
        email,
        password,
      } satisfies ITodoUser.ICreate,
    });
  typia.assert(authorizedUser);

  // 2. Create user account with the same email
  const createdUser: ITodoUser = await api.functional.todo.todoUsers.create(
    connection,
    {
      body: {
        email,
        password,
      } satisfies ITodoUser.ICreate,
    },
  );
  typia.assert(createdUser);
  // Assert that email matches
  TestValidator.equals(
    "created user email matches input",
    createdUser.email,
    email,
  );

  // 3. Update user password by providing new password
  const newPassword: string = RandomGenerator.alphaNumeric(16);
  const updatedUser: ITodoUser =
    await api.functional.todo.user.todoUsers.update(connection, {
      todoUserEmail: email, // path parameter identifies user
      body: {
        password: newPassword,
      } satisfies ITodoUser.IUpdate,
    });
  typia.assert(updatedUser);

  // 4. Validate that updated user's email is unchanged and other timestamps are valid
  TestValidator.equals(
    "updated user email unchanged",
    updatedUser.email,
    email,
  );
  TestValidator.predicate(
    "created_at looks like ISO date-time",
    typeof updatedUser.created_at === "string" &&
      updatedUser.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at looks like ISO date-time",
    typeof updatedUser.updated_at === "string" &&
      updatedUser.updated_at.length > 0,
  );
  TestValidator.predicate(
    "deleted_at is either null or string",
    updatedUser.deleted_at === null ||
      typeof updatedUser.deleted_at === "string" ||
      updatedUser.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";

/**
 * Validate permanent deletion of a user account by email.
 *
 * This test performs the following steps:
 *
 * 1. Authenticate as a new user with a randomly generated email and password.
 * 2. Create a new todo user account with a unique email and password.
 * 3. Delete the created user account permanently using the email address.
 * 4. Confirm deletion by asserting no error occurs during deletion.
 *
 * All API calls strictly follow the provided DTO types and assert responses for
 * correctness with typia.assert. Random valid data conforming to required
 * formats are generated using typia.random and RandomGenerator.
 */
export async function test_api_user_permanent_deletion_by_email(
  connection: api.IConnection,
) {
  // 1. Join user to authenticate and obtain a token
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password = RandomGenerator.alphaNumeric(12);

  const authorizedUser: ITodoUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: { email, password } satisfies ITodoUser.ICreate,
    });
  typia.assert(authorizedUser);

  // 2. Create a user account to be deleted; here email must be unique, generate new
  const newEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const newPassword = RandomGenerator.alphaNumeric(12);
  const createdUser: ITodoUser = await api.functional.todo.todoUsers.create(
    connection,
    {
      body: {
        email: newEmail,
        password: newPassword,
      } satisfies ITodoUser.ICreate,
    },
  );
  typia.assert(createdUser);
  TestValidator.equals(
    "created user's email matches",
    createdUser.email,
    newEmail,
  );

  // 3. Delete user account permanently by email
  await api.functional.todo.user.todoUsers.erase(connection, {
    todoUserEmail: newEmail,
  });

  // 4. Verification that deletion succeeded is implicit as no errors thrown; also
  // further validation like query is not defined, so test ends here
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUser";
import type { ITodoUserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoUserSession";

/**
 * Validate the user session creation workflow.
 *
 * This test covers the complete business flow of creating a new user session
 * for an authenticated user identified by their email.
 *
 * Step-by-step process:
 *
 * 1. Create a user account using the signup API (/todo/todoUsers).
 * 2. Authenticate as the user via the join API (/auth/user/join).
 * 3. Create a new session for the user using IP, href, and referrer metadata via
 *    the session creation API (/todo/user/todoUsers/{email}/sessions).
 * 4. Validate the returned session metadata for correctness and completeness.
 *
 * The test ensures that sessions can only be created for authenticated users,
 * that session metadata is recorded accurately, and that the workflow enforces
 * proper authorization.
 */
export async function test_api_user_session_creation(
  connection: api.IConnection,
) {
  // 1. Create a new user account first
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password = RandomGenerator.alphaNumeric(12);

  const user: ITodoUser = await api.functional.todo.todoUsers.create(
    connection,
    {
      body: {
        email: email,
        password: password,
      } satisfies ITodoUser.ICreate,
    },
  );
  typia.assert(user);
  TestValidator.predicate(
    "user ID is a UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
      user.id,
    ),
  );

  // 2. Join/authenticate as that user
  const authorized: ITodoUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: {
        email: email,
        password: password,
      } satisfies ITodoUser.ICreate,
    },
  );
  typia.assert(authorized);
  TestValidator.equals(
    "authorized user ID matches created user ID",
    authorized.id,
    user.id,
  );

  // 3. Create a new session for the authenticated user
  const ip =
    "192.168." +
    RandomGenerator.alphaNumeric(2) +
    "." +
    RandomGenerator.alphaNumeric(2);
  const hrefUrl = `https://example.com/todo?user=${encodeURIComponent(email)}`;
  const referrerUrl = `https://referrer.example.co/path?arg=value`;

  const session: ITodoUserSession =
    await api.functional.todo.user.todoUsers.sessions.create(connection, {
      todoUserEmail: email,
      body: {
        ip: ip,
        href: hrefUrl,
        referrer: referrerUrl,
      } satisfies ITodoUserSession.ICreate,
    });
  typia.assert(session);

  // 4. Validate the returned session data
  TestValidator.equals(
    "session todo_user_id matches user id",
    session.todo_user_id,
    user.id,
  );
  TestValidator.predicate(
    "session id is a UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
      session.id,
    ),
  );
  TestValidator.equals("session ip matches input", session.ip, ip);
  TestValidator.equals("session href matches input", session.href, hrefUrl);
  TestValidator.equals(
    "session referrer matches input",
    session.referrer,
    referrerUrl,
  );
  TestValidator.predicate(
    "session created_at is ISO 8601",
    !isNaN(Date.parse(session.created_at)),
  );

  // session expired_at may be null or undefined when active
  TestValidator.predicate(
    "session expired_at is null or undefined",
    session.expired_at === null || session.expired_at === undefined,
  );
}

