  const userEmail = `${RandomGenerator.name(1)}.${RandomGenerator.name(1)}@example.com`;
  const userAuthorized: ITodoUser.IAuthorized =
    await api.functional.auth.user.join(connection, {
      body: {
        email: userEmail,
        password: "Passw0rd!",
      } satisfies ITodoUser.ICreate,
