  todoUserEmail: string;
  body: ITodoUser.IUpdate;
}): Promise<ITodoUser> {
  const userRecord = await MyGlobal.prisma.todo_users.findFirst({
    where: {
      email: props.todoUserEmail,
      deleted_at: null,
    },
  });

  if (!userRecord) {
